CREATE UNIQUE INDEX "RoleNameIndex" ON "AppRole" ("NormalizedName");

CREATE INDEX "IX_AppRoleClaim_RoleId" ON "AppRoleClaim" ("RoleId");

CREATE INDEX "EmailIndex" ON "AppUser" ("NormalizedEmail");

CREATE UNIQUE INDEX "UserNameIndex" ON "AppUser" ("NormalizedUserName");

CREATE INDEX "IX_AppUserClaim_UserId" ON "AppUserClaim" ("UserId");

CREATE INDEX "IX_AppUserLogin_UserId" ON "AppUserLogin" ("UserId");

CREATE INDEX "IX_AppUserRole_RoleId" ON "AppUserRole" ("RoleId");

CREATE INDEX "IX_Cargos_DepartamentoId_DepartamentoCodigo" ON "Cargos" ("DepartamentoId", "DepartamentoCodigo");

CREATE INDEX "IX_PerfilDeAcessoModulos_ModuloId_ModuloCodigo" ON "PerfilDeAcessoModulos" ("ModuloId", "ModuloCodigo");

CREATE INDEX "IX_PerfilDeAcessoUsuarios_UsuarioId_UsuarioCodigo" ON "PerfilDeAcessoUsuarios" ("UsuarioId", "UsuarioCodigo");

CREATE INDEX "IX_PerfisDeAcesso_UsuarioId_UsuarioCodigo" ON "PerfisDeAcesso" ("UsuarioId", "UsuarioCodigo");

CREATE UNIQUE INDEX "IX_Salarios_UsuarioId_UsuarioCodigo" ON "Salarios" ("UsuarioId", "UsuarioCodigo");

CREATE INDEX "IX_Tarefas_UsuarioId_UsuarioCodigo" ON "Tarefas" ("UsuarioId", "UsuarioCodigo");

CREATE INDEX "IX_UsuarioCargoDepartamento_CargoId_CargoCodigo" ON "UsuarioCargoDepartamento" ("CargoId", "CargoCodigo");

CREATE INDEX "IX_UsuarioCargoDepartamento_DepartamentoId_DepartamentoCodigo" ON "UsuarioCargoDepartamento" ("DepartamentoId", "DepartamentoCodigo");

SELECT setval(
    pg_get_serial_sequence('"Modulos"', 'Id'),
    GREATEST(
        (SELECT MAX("Id") FROM "Modulos") + 1,
        nextval(pg_get_serial_sequence('"Modulos"', 'Id'))),
    false);

